"""Deterministic link sources; no URL is generated by the analysis model."""

import re
from collections.abc import Sequence

from apiReading.models import ReadingResult
from textAnalysis.container import AnalysisDataContainer

from .protocols import CandidateLink
from .url_validation import InvalidUrlError, validate_url

_URL_PATTERN = re.compile(r"https?://[^\s<>\"']+", re.IGNORECASE)
MAX_TEXT_SCAN_CHARS = 50_000
MAX_TEXT_MATCHES = 50
MAX_LINKS = 5
MAX_USER_TEXT_LINKS = 2


def _strip_trailing_punctuation(url: str) -> str:
    while url and url[-1] in ".,;:!?":
        url = url[:-1]
    while url.endswith(")") and url.count(")") > url.count("("):
        url = url[:-1]
    while url.endswith("]") and url.count("]") > url.count("["):
        url = url[:-1]
    while url.endswith("}") and url.count("}") > url.count("{"):
        url = url[:-1]
    return url


class TextLinkSource:
    """Extract a small, bounded number of links directly present in user text."""

    def extract(
        self,
        analysis: AnalysisDataContainer,
        reading_results: Sequence[ReadingResult] = (),
    ) -> list[CandidateLink]:
        del reading_results
        text = analysis.original_text or analysis.source_text
        matches = _URL_PATTERN.finditer(text[:MAX_TEXT_SCAN_CHARS])
        links: list[CandidateLink] = []
        for match in matches:
            url = _strip_trailing_punctuation(match.group(0))
            if url:
                links.append(CandidateLink(url=url, source="user_text"))
            if len(links) >= MAX_TEXT_MATCHES:
                break
        return links


class FactCheckLinkSource:
    """Collect publisher article URLs returned by fact-check providers."""

    def extract(
        self,
        analysis: AnalysisDataContainer,
        reading_results: Sequence[ReadingResult] = (),
    ) -> list[CandidateLink]:
        del analysis
        links: list[CandidateLink] = []
        for result in reading_results:
            for item in result.items:
                payload = item.payload
                reviews = payload.get("claimReview") or []
                if isinstance(reviews, list):
                    for review in reviews:
                        if isinstance(review, dict) and isinstance(review.get("url"), str):
                            links.append(CandidateLink(url=review["url"], source="fact_check"))
                if isinstance(payload.get("url"), str):
                    links.append(CandidateLink(url=payload["url"], source="fact_check"))
        return links


def extract_links(
    analysis: AnalysisDataContainer,
    reading_results: Sequence[ReadingResult] = (),
) -> list[str]:
    """Return normalized unique candidates, fact-check URLs before user URLs."""
    sources = (FactCheckLinkSource(), TextLinkSource())
    candidates = [
        candidate for source in sources for candidate in source.extract(analysis, reading_results)
    ]
    selected, _ = select_candidates(candidates)
    return [candidate.url for candidate in selected]


def select_candidates(
    candidates: Sequence[CandidateLink],
    max_links: int = MAX_LINKS,
    max_user_links: int = MAX_USER_TEXT_LINKS,
) -> tuple[list[CandidateLink], list[tuple[CandidateLink, str]]]:
    """Canonicalize and apply shared deduplication and per-source link limits."""

    prioritized = sorted(candidates, key=lambda candidate: candidate.source != "fact_check")
    selected: list[CandidateLink] = []
    rejected: list[tuple[CandidateLink, str]] = []
    seen: set[str] = set()
    user_text_count = 0
    for candidate in prioritized:
        try:
            url = validate_url(candidate.url)
        except InvalidUrlError:
            rejected.append((candidate, "InvalidUrl"))
            continue
        if url in seen:
            continue
        seen.add(url)
        if len(selected) >= max_links or (
            candidate.source == "user_text" and user_text_count >= max_user_links
        ):
            rejected.append((CandidateLink(url=url, source=candidate.source), "LinkLimitExceeded"))
            continue
        selected.append(CandidateLink(url=url, source=candidate.source))
        if candidate.source == "user_text":
            user_text_count += 1
    return selected, rejected
